import {partyFX} from './party-fx.js';
import {MazeGame,DIRECTIONS} from './maze-engine.js';
import {loadWords} from './word-store.js';
import {readWords} from './vocab.js';
import {bindGameLifecycle} from './game-lifecycle.js';
const $=id=>document.getElementById(id);let game=null,paused=false,last=0,held=null,pointerId=null,finished=false,messageUntil=0;
const terrain=document.createElement('div');terrain.className='terrain';const actors=document.createElement('div');actors.className='actors';$('maze').append(terrain,actors);const cells=[];for(let i=0;i<81;i++){const c=document.createElement('div');c.className='cell';terrain.append(c);cells.push(c);}const actorNodes=new Map();
function clear(){held=null;pointerId=null;game?.stop();for(const b of document.querySelectorAll('[data-dir]'))b.classList.remove('pressed');}
function note(t){$('status').textContent=t;messageUntil=performance.now()+1700;}
let fxState=null;function trackEffects(g){const next={hp:g.hp,kills:g.kills,destroyed:g.destroyed,bombs:g.bombs.length};if(fxState){if(g.hp<fxState.hp)partyFX.burst('miss','爆風に注意！');else if(g.kills>fxState.kills)partyFX.reward('enemy-'+g.kills,'敵を撃破',20,0,$('maze'));else if(g.destroyed>fxState.destroyed||g.bombs.length<fxState.bombs)partyFX.burst('boom','BOOM!',$('maze'));}fxState=next;}
function start(){partyFX.resetRewards();fxState=null;const p=readWords(loadWords());try{if(p.errors.length)throw Error(p.errors[0]);game=new MazeGame(p.entries);}catch(e){$('error').textContent=e.message;return;}clear();paused=false;finished=false;for(const id of['intro','result','quizScreen','pauseScreen'])$(id).classList.add('hidden');note('爆弾を置いたら、曲がり角へ逃げよう！');render();}
function render(){if(!game)return;const g=game;trackEffects(g);const danger=new Set(g.bombs.flatMap(b=>g.blastCells(b).map(c=>c.x+','+c.y)));cells.forEach((c,i)=>{const x=i%9,y=Math.floor(i/9),tile=g.grid[y][x],bomb=g.bombs.find(b=>b.x===x&&b.y===y),fire=g.flames.some(f=>f.x===x&&f.y===y),exit=x===7&&y===7;const cls='cell'+(tile===1?' hard':tile===2?' crate':'')+(exit?' exit':'')+(exit&&!g.enemies.length?' unlocked':'')+(fire?' fire':danger.has(x+','+y)?' danger':'')+(bomb&&bomb.life<.8?' urgent':'');if(c.className!==cls)c.className=cls;const text=fire?'✹':bomb?'💣':exit?(g.enemies.length?'🔒':'🚪'):tile===2?'╳':'';if(c.textContent!==text)c.textContent=text;const timer=bomb?bomb.life.toFixed(1):'';if(c.dataset.timer!==timer)c.dataset.timer=timer;});const list=[[g.player,'🐥'],...g.enemies.map(e=>[e,e.kind==='chaser'?'😈':'👾'])],live=new Set(list.map(([a])=>a));for(const [a,n]of actorNodes)if(!live.has(a)){n.remove();actorNodes.delete(a);}for(const [a,emoji]of list){let n=actorNodes.get(a);if(!n){n=document.createElement('div');n.className='actor';n.textContent=emoji;actors.append(n);actorNodes.set(a,n);}n.style.transform=`translate3d(${a.x*100}%,${a.y*100}%,0)`;n.classList.toggle('hurt',a===g.player&&g.invincible>0);}
$('health').textContent='♥'.repeat(g.hp)+'♡'.repeat(3-g.hp);$('time').textContent=Math.ceil(g.time)+'秒';$('ammo').textContent='爆弾 '+g.ammo;$('place').disabled=paused||!!g.quiz||g.mode!=='play'||!g.ammo||g.bombs.length>=2;$('refill').disabled=paused||!!g.quiz||g.mode!=='play'||g.ammo>=4;if(performance.now()>messageUntil)$('status').textContent=g.enemies.length?'敵あと'+g.enemies.length+'体 · 木箱破壊 '+g.destroyed:'出口が開いた！ 右下のドアへ';if(g.mode!=='play'&&!finished){finished=true;clear();if(g.mode==='won')partyFX.reward('clear','脱出成功',50);else partyFX.burst('miss','もう一度！');$('resultTitle').textContent=g.mode==='won'?'迷路から脱出！':'もう一度チャレンジ！';$('resultScore').textContent='敵 '+g.kills+' / 3体';$('resultStats').textContent=`木箱${g.destroyed}個破壊 · 単語${g.correct}/${g.answered}問正解`;$('review').replaceChildren();for(const p of g.review.values()){const r=document.createElement('p');r.textContent=p.word+' ＝ '+p.meaning;$('review').append(r);}$('result').classList.remove('hidden');}}
function pause(v){if(!game||game.mode!=='play')return;paused=v;if(v)partyFX.clear();clear();$('pauseScreen').classList.toggle('hidden',!v);render();}
for(const b of document.querySelectorAll('[data-dir]')){b.addEventListener('pointerdown',e=>{if(!game||paused||game.quiz||game.mode!=='play'||pointerId!==null)return;e.preventDefault();pointerId=e.pointerId;held=Number(b.dataset.dir);try{b.setPointerCapture(e.pointerId);}catch{}game.move(...DIRECTIONS[held]);render();});for(const event of['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,e=>{if(e.pointerId===pointerId)clear();});b.addEventListener('contextmenu',e=>e.preventDefault());}
document.querySelector('.dpad').addEventListener('pointermove',e=>{if(e.pointerId!==pointerId)return;e.preventDefault();const r=document.querySelector('.dpad').getBoundingClientRect(),x=e.clientX-r.left-r.width/2,y=e.clientY-r.top-r.height/2;held=Math.hypot(x,y)<12?null:Math.abs(x)>Math.abs(y)?(x>0?1:3):(y>0?2:0);if(held===null)game?.stop();else game?.move(...DIRECTIONS[held]);});
function refill(){if(!game||paused||!game.openQuiz())return;clear();$('quizTitle').textContent=game.quiz.target.meaning;$('quizFeedback').textContent='正解で爆弾を2個補充！';$('closeQuiz').textContent='補充せずに戻る';$('choices').replaceChildren();game.quiz.choices.forEach((p,i)=>{const b=document.createElement('button');b.className='secondary';b.textContent=p.word;b.onclick=()=>{if(paused)return;const ok=game.answerQuiz(i);if(ok===null)return;if(ok)partyFX.reward('quiz-'+game.correct,'補充成功',10);else partyFX.burst('miss','正解をチェック！');for(const n of $('choices').children)n.disabled=true;$('quizFeedback').textContent=ok?'正解！ 爆弾 ＋2':`正解は ${game.quiz.target.word} ＝ ${game.quiz.target.meaning}`;$('closeQuiz').textContent='迷路に戻る';render();};$('choices').append(b);});$('quizScreen').classList.remove('hidden');render();}
$('start').onclick=start;$('again').onclick=start;$('place').onclick=()=>{if(!paused){if(game?.place())note('置いた！ 爆風から逃げよう！');else note('爆弾を補充するか、置いた爆弾の爆発を待とう');render();}};$('refill').onclick=refill;$('closeQuiz').onclick=()=>{game?.closeQuiz();clear();$('quizScreen').classList.add('hidden');render();};$('pause').onclick=()=>pause(true);$('resume').onclick=()=>pause(false);bindGameLifecycle(window,document,{clearInput:reason=>{if(reason!=='blur'||pointerId===null)clear();},pause});
const keyDirs={ArrowUp:0,w:0,ArrowRight:1,d:1,ArrowDown:2,s:2,ArrowLeft:3,a:3};window.addEventListener('keydown',e=>{if(e.key==='Escape'){pause(!paused);return;}if(!game||paused||game.quiz||game.mode!=='play')return;const d=keyDirs[e.key];if(d!==undefined){e.preventDefault();held=d;}if(e.code==='Space'){e.preventDefault();if(!e.repeat)$('place').click();}if(e.key==='q'&&!e.repeat)refill();});window.addEventListener('keyup',e=>{if(keyDirs[e.key]!==undefined)clear();});function frame(t){const dt=last?Math.min(.1,(t-last)/1000):0;last=t;if(game&&!paused&&!document.hidden&&game.mode==='play'){if(held!==null)game.move(...DIRECTIONS[held]);else game.stop();game.tick(dt);for(const b of document.querySelectorAll('[data-dir]'))b.classList.toggle('pressed',Number(b.dataset.dir)===held);render();}requestAnimationFrame(frame);}requestAnimationFrame(frame);
